import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, texture, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    Vector2,
    Color
  } = THREE;

  const root = new Group();
  root.name = 'pricing-card-1';
  root.userData.handlers = {};

  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  const resources = [];
  const cleanupTasks = [];

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropY = uv().y;
  backdropMaterial.colorNode = mix(
    vec3(color(surface)),
    mix(vec3(color(ink)), vec3(color('#25252d')), backdropY),
    backdropY
  );
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const shadowGeometry = new PlaneGeometry(3.2, 1.95);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: new Color(surface),
    transparent: true,
    opacity: 0.52,
    depthWrite: false
  });
  const contactShadow = new Mesh(shadowGeometry, shadowMaterial);
  contactShadow.name = 'pricing-card-contact-shadow';
  contactShadow.position.set(0, -0.08, -0.08);
  contactShadow.scale.set(1.08, 0.72, 1);
  root.add(contactShadow);
  resources.push(shadowGeometry, shadowMaterial);

  const cardGroup = new Group();
  cardGroup.name = 'pricing-card-sprite';
  cardGroup.position.z = 0.08;
  root.add(cardGroup);

  const backingGeometry = new BoxGeometry(2.72, 1.72, 0.12);
  const backingMaterial = new MeshBasicNodeMaterial({
    color: new Color(ink)
  });
  const backing = new Mesh(backingGeometry, backingMaterial);
  backing.name = 'machined-card-backing';
  cardGroup.add(backing);
  resources.push(backingGeometry, backingMaterial);

  const imageGeometry = new PlaneGeometry(2.56, 1.6);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: new Color(paper),
    transparent: true
  });
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.name = 'pricing-card-atlas-sprite';
  imagePlane.position.z = 0.075;
  cardGroup.add(imagePlane);
  resources.push(imageGeometry, imageMaterial);

  const accentGeometry = new BoxGeometry(0.72, 0.035, 0.025);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: new Color(accent)
  });
  const accentBar = new Mesh(accentGeometry, accentMaterial);
  accentBar.name = 'signal-red-accent';
  accentBar.position.set(-0.88, -0.92, 0.11);
  root.add(accentBar);
  resources.push(accentGeometry, accentMaterial);

  const billboard = (_, __, camera) => {
    imagePlane.quaternion.copy(camera.quaternion);
    backing.quaternion.copy(camera.quaternion);
    accentBar.quaternion.copy(camera.quaternion);
  };
  imagePlane.onBeforeRender = billboard;
  backing.onBeforeRender = billboard;
  accentBar.onBeforeRender = billboard;

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  let loadedTexture = null;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      loadedTexture = tex;
      if (tex.colorSpace !== undefined && THREE.SRGBColorSpace !== undefined) {
        tex.colorSpace = THREE.SRGBColorSpace;
      }

      tex.offset = tex.offset ?? new Vector2();
      tex.repeat = tex.repeat ?? new Vector2(1, 1);
      tex.offset.set(0, 0);
      tex.repeat.set(1, 1);

      imageMaterial.map = texture(tex);
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    cardGroup.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.42, ease: 'power3.out' }
  ).to(
    cardGroup.scale,
    { x: 1, y: 1, z: 1, duration: 0.48, ease: 'power4.out' }
  );

  root.userData.cleanup = () => {
    entrance.kill();

    for (const task of cleanupTasks) {
      try {
        task();
      } catch (_) {}
    }

    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }

    for (const resource of resources) {
      if (resource && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    }

    root.traverse((object) => {
      object.onBeforeRender = null;
    });
  };

  return root;
}
